        private static (string host, int port, ConfigurationOptions options) GetRedisSettings()
        {
            var options = new ConfigurationOptions();
            var url = Environment.GetEnvironmentVariable("REDIS_URL");
            if (string.IsNullOrWhiteSpace(url))
            {
                return ("redis", 6379, options);
            }

            var uri = new Uri(url);
            var userInfo = uri.UserInfo.Split(':', 2);
            var user = Uri.UnescapeDataString(userInfo[0]);
            if (user.Length > 0 && user != "default")
            {
                options.User = user;
            }
            if (userInfo.Length > 1)
            {
                options.Password = Uri.UnescapeDataString(userInfo[1]);
            }
            if (uri.Scheme == "rediss")
            {
                options.Ssl = true;
                options.SslHost = uri.DnsSafeHost;
            }
            return (uri.DnsSafeHost, uri.Port > 0 ? uri.Port : 6379, options);
